            "pub(super) struct Canonicalizer",
            "pub(in crate::cleanup_plan::replay::factored) struct Canonicalizer",
        )
        .replace(
            "    pub(super) fn new(",
            "    pub(in crate::cleanup_plan::replay::factored) fn new(",
